/// <summary>
/// Initializing the form data source EcoResProductTranslation.
/// </summary>
public void init()
{
    QueryBuildDataSource qbds;
    QueryBuildRange      qbr;

    next init();

    qbds = this.query().dataSourceTable(tableNum(EcoResProductTranslation));

    qbr = qbds.addRange(fieldNum(EcoResProductTranslation, LanguageId));
    qbr.value(queryValue(SystemParameters::getSystemLanguageId()));
    qbr.status(RangeStatus::Hidden);
}
